"""Archive sealed v2 model deliveries with deterministic size-limited parts."""
import copy
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).parent
DEST = Path('/home/zhongming/CodeNib-codegraph-benefit/docs/experiments')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(name, value):
    path = DEST / name
    data = json.dumps(value, indent=2) + '\n'
    assert len(data.encode()) < 500 * 1024, (name, len(data.encode()))
    if path.exists():
        assert path.read_text() == data, 'Never replace an existing v2 capture'
    else:
        path.write_text(data)
    return {'artifact': name, 'sha256': sha(path)}


def archive():
    launch = json.loads((ROOT / 'sequential-launch-v2.json').read_text())
    assert launch.get('finished_utc'), 'Archive final results only after the model batch is sealed'
    manifest = []
    for path in sorted((ROOT / 'matched-runs-v2').glob('*/receipt.json')):
        raw = json.loads(path.read_text())
        assert raw.get('finished_utc')
        folder, index = path.parent, raw['workflow']['workflow_index']
        projection = copy.deepcopy(raw)
        for session in projection['sessions']:
            relevant = [p for p in raw['phases'] if p['session'] == session['name'] and p.get('result')]
            session['results'] = [{'phase_result_reference': p['kind']} for p in relevant]
            if session.get('final_result') and relevant:
                session['final_result']['result'] = {'phase_answer_reference': relevant[-1]['kind']}
        observations, sources = {}, {}
        for phase in raw['phases']:
            for label in ['source_before', 'source_after']:
                item = phase.get(label)
                if item:
                    source = Path(item['path'])
                    assert sha(source) == item['sha256']
                    sources.setdefault(item['sha256'], {'text': source.read_text(), 'original_names': []})['original_names'].append(source.name)
            if not phase.get('trace'):
                continue
            trace = folder / phase['trace']['path']
            assert sha(trace) == phase['trace']['sha256']
            calls, deliveries, init, rates = {}, [], [], []
            for line in trace.read_text().splitlines():
                event = json.loads(line)
                if event.get('type') == 'AssistantMessage':
                    for block in event['content']:
                        if block.get('name') and block.get('id'):
                            if block['id'] in calls: assert calls[block['id']] == block
                            calls[block['id']] = block
                elif event.get('type') == 'UserMessage': deliveries.append(event)
                elif event.get('type') == 'SystemMessage': init.append(event)
                elif event.get('type') == 'RateLimitEvent': rates.append(event)
            value = {'scope': 'Exact captured v2 tool requests and delivered user/tool messages; no task acceptance or complete source-read score.', 'workflow_index': index, 'task_id': phase['task_id'], 'kind': phase['kind'], 'raw_sdk_trace_sha256': sha(trace), 'raw_sdk_trace_bytes': trace.stat().st_size, 'init': init, 'rate_events': rates, 'tool_calls_in_first_observed_order': list(calls.values()), 'delivered_user_tool_messages_in_order': deliveries}
            observations[phase['kind']] = write(f'codegraph_matched_workflow_v2_{index:02d}_{phase["kind"]}_observations.json', value)
        source_ref = write(f'codegraph_matched_workflow_v2_{index:02d}_sources.json', {'scope': 'Actual source-version receipts, not model-read credit.', 'source_snapshot_captures_by_sha256': sources})
        hooks_path = folder / 'hooks.jsonl'
        hooks = [json.loads(line) for line in hooks_path.read_text().splitlines()] if hooks_path.exists() else []
        hook_ref = write(f'codegraph_matched_workflow_v2_{index:02d}_tool_inputs.json', {
            'scope': 'Original pre-tool requests, permissions, effective scoped inputs and SDK output registration receipts. Post-tool response bytes are retained in original hooks and delivered model/tool observations, not duplicated here.',
            'raw_hooks_sha256': sha(hooks_path) if hooks_path.exists() else None,
            'raw_hooks_bytes': hooks_path.stat().st_size if hooks_path.exists() else None,
            'pre_tool_and_output_registration_events': [h for h in hooks if h.get('event') != 'post']})
        value = {'schema_version': 2, 'scope': 'Independent prospectively frozen v2 model execution. Original v1 remains unchanged; source/native acceptance is separate.', 'original_receipt': str(path), 'original_receipt_sha256': sha(path), 'receipt_projection': projection, 'projection_rule': 'Phase results/answers retained; duplicate cumulative session answers link to their phase. Exact tool deliveries, original pre-tool inputs and source snapshots are separately hash-bound. Intermediate visible prose/stream usage remain in the original SDK traces and are not summed as cumulative usage.', 'phase_observations': observations, 'source_snapshots': source_ref, 'original_tool_inputs': hook_ref, 'repair_patch': (folder / 'repair.patch').read_text() if (folder / 'repair.patch').exists() else None, 'setup_patch': (folder / 'pre-model.patch').read_text() if (folder / 'pre-model.patch').exists() else None, 'source_credit': 'No complete ContextBench read score. Arbitrary shell output remains unattributed until source-version/file mapping is verified.', 'archive_implementation_sha256': sha(__file__)}
        ref = write(f'codegraph_matched_workflow_v2_{index:02d}.json', value)
        ref.update(workflow=raw['workflow'], original_receipt_sha256=sha(path))
        manifest.append(ref)
        print(json.dumps({'workflow_index': index, 'archived_phases': len(observations), 'artifact': ref['artifact']}), flush=True)
    write('codegraph_matched_v2_capture_manifest.json', {'scope': 'Sealed v2 captured observations, before separate acceptance; original v1 remains unchanged.', 'launch': launch, 'workflows': manifest, 'archive_implementation': {'sha256': sha(__file__), 'source': Path(__file__).read_text()}})


if __name__ == '__main__':
    archive()

