import hashlib,json
from pathlib import Path
import flask.app,flask.ctx,flask.helpers
from flask import Flask,Response,stream_with_context,request,has_request_context
modules={'app.py':flask.app,'ctx.py':flask.ctx,'helpers.py':flask.helpers}
observed={name:hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest() for name,module in modules.items()}
assert observed=={'app.py': 'd439102c7658f90f896556c557df89501f2c98ad498d6317453f10ef58508710', 'ctx.py': '6c611042e176fdc1ea67764d31e31e106f0738b2640e52fcf2ed810710ab45aa', 'helpers.py': 'efa15481302a200fabae2498f5e6ff9ae002906bd0ad9550b91a32269d4a4c1e'}
checks={}
app=Flask('stream-context-source-audit');events=[]
@app.teardown_request
def teardown(exc):events.append('teardown')
@app.route('/')
def view():
    def body():yield request.path.encode()
    return Response(stream_with_context(body()))
def probe(app):
    with app.test_request_context('/'):
        return app.full_dispatch_request()
response=probe(app)
checks['wrapped_stream_keeps_request_context_after_probe_return']=has_request_context()
checks['teardown_not_yet_run_at_probe_return']=events==[]
body=b''.join(response.response)
checks['wrapped_stream_reads_request_after_probe_return']=body==b'/'
response.close()
checks['teardown_after_stream_finishes']=events==['teardown']
checks['request_context_gone_after_stream_finishes']=not has_request_context()
app=Flask('propagation-source-audit');app.logger.disabled=True
app.config.update(PROPAGATE_EXCEPTIONS=False,DEBUG=True,TESTING=False)
with app.test_request_context('/'):
    response=app.handle_exception(ValueError('controlled'))
    checks['explicit_false_with_debug_returns_500']=response.status_code==500
print(json.dumps({'source_sha256':observed,'checks':checks}))
assert all(checks.values())

